INSERT INTO `page_sections` (`id`, `page_key`, `section_key`, `title`, `is_active`, `sort_order`, `config`, `updated_at`) VALUES (31,'home','hero','hero',1,0,'{\"eyebrow\":\"ไทยประกันชีวิต สาขาบางนา\",\"h1Spans\":[\"วางแผนประกันชีวิต สุขภาพ\",\"และมรดกกับทีมที่ดูแลจริง\"],\"copy\":\"ให้คำปรึกษาโดยทีมผู้บริหารศูนย์และผู้บริหารหน่วยไทยประกันชีวิต พร้อมช่วยดูแลแผน คำถาม เอกสาร และการประสานงานเคลมหลังทำกรมธรรม์\",\"slides\":[{\"src\":\"assets\\/cover\\/cover1.png\",\"alt\":\"ครอบครัววางแผนชีวิตในบ้านโทนสีฟ้าขาว\",\"width\":\"1922\",\"height\":\"818\",\"ratio\":\"1922 \\/ 818\",\"active\":true},{\"src\":\"assets\\/cover\\/cover 2.png\",\"alt\":\"ลูกค้านั่งใช้งานมือถือในพื้นที่สว่างโทนสีฟ้าขาว\",\"width\":\"1821\",\"height\":\"864\",\"ratio\":\"1821 \\/ 864\",\"active\":false},{\"src\":\"assets\\/cover\\/cover 3.png\",\"alt\":\"ลูกค้าในอาคารโรงพยาบาลโทนสีฟ้าขาว\",\"width\":\"1770\",\"height\":\"888\",\"ratio\":\"1770 \\/ 888\",\"active\":false}]}','2026-05-26 20:28:36'),(32,'home','solutionsHeading','แผนหลักจากข้อมูลแบบประกันที่เหมาะกับหลายช่วงชีวิต',1,1,'{\"eyebrow\":\"แบบประกันแนะนำ\",\"h2\":\"แผนหลักจากข้อมูลแบบประกันที่เหมาะกับหลายช่วงชีวิต\",\"lead\":\"\"}','2026-05-26 14:21:03'),(33,'home','productCategories','แบบประกันทั้งหมด',1,2,'{\"h2\":\"แบบประกันทั้งหมด\",\"chips\":[{\"href\":\"life-insurance.html\",\"image\":\"assets\\/icon\\/Layer 3.png\",\"label\":\"เลกาซี ฟิต แคร์ 99\\/10\"},{\"href\":\"life-insurance.html\",\"image\":\"assets\\/icon\\/Layer 2.png\",\"label\":\"คุ้มธนกิจ 99\\/20 (Nn)\"},{\"href\":\"health-insurance.html\",\"image\":\"assets\\/icon\\/Layer 5.png\",\"label\":\"Health Fit DD\"},{\"href\":\"savings-retirement.html\",\"image\":\"assets\\/icon\\/Layer 2.png\",\"label\":\"ทีแอลแพลน\"},{\"href\":\"savings-retirement.html\",\"image\":\"assets\\/icon\\/Layer 4.png\",\"label\":\"มันนี่ ฟิต เวลท์ตี้ 18\\/4\"}]}','2026-05-26 14:21:03'),(34,'home','intro','เลือกบริษัทที่มั่นคง และมีคนดูแลระยะยาว',1,3,'{\"eyebrow\":\"Thai Life Insurance planning\",\"h2\":\"เลือกบริษัทที่มั่นคง และมีคนดูแลระยะยาว\",\"lead\":\"ไทยประกันชีวิตเป็นบริษัทคนไทยที่อยู่มายาวนาน แผนคุ้มครองครอบคลุมทั้งค่ารักษา โรคร้ายแรง รายได้ระหว่างพักรักษา และความคุ้มครองชีวิต เหมาะกับคนที่อยากวางแผนให้จบครบในกรมธรรม์เดียว\",\"tags\":[{\"title\":\"บริษัทคนไทย มั่นคงยาวนาน\"},{\"title\":\"คุ้มครองครบวงจร\"},{\"title\":\"วางแผนได้ในกรมธรรม์เดียว\"}],\"imageSrc\":\"assets\\/thai-life-company-promo.png\",\"imageAlt\":\"ไทยประกันชีวิต บริษัทคนไทยที่อยู่มายาวนาน คุ้มครองครบในกรมธรรม์เดียว\"}','2026-05-26 14:21:03'),(35,'home','process','ดูแลตั้งแต่เลือกแผนจนถึงหลังออกกรมธรรม์',1,4,'{\"eyebrow\":\"วิธีทำงาน\",\"h2\":\"ดูแลตั้งแต่เลือกแผนจนถึงหลังออกกรมธรรม์\",\"copy\":\"เริ่มจากเข้าใจเป้าหมายชีวิตก่อน แล้วค่อยคัดแบบประกันที่เหมาะกับงบ ความคุ้มครอง และเงื่อนไขจริง\",\"linkText\":\"เริ่มปรึกษาฟรี\",\"linkHref\":\"contact.html\",\"steps\":[{\"num\":\"01\",\"title\":\"สำรวจเป้าหมายและสุขภาพ\",\"desc\":\"คุยเรื่องครอบครัว รายได้ ภาระหนี้ สุขภาพ งบประมาณ และสิทธิลดหย่อนภาษีที่ต้องการใช้\"},{\"num\":\"02\",\"title\":\"เลือกแบบประกันที่เหมาะ\",\"desc\":\"เทียบจุดเด่นของแผน เช่น ชำระเบี้ยสั้น คุ้มครองยาว เงินคืน ค่ารักษา และผลประโยชน์เมื่อครบสัญญา\"},{\"num\":\"03\",\"title\":\"ช่วยประสานงานหลังสมัคร\",\"desc\":\"มีทีมดูแลเอกสาร คำถามกรมธรรม์ และช่วยประสานงานเมื่อต้องใช้สิทธิหรือยื่นเคลม\"}]}','2026-05-26 14:21:03'),(36,'home','taxPlansHeading','เลือกประเภทแบบประกันไทยประกันชีวิต',1,5,'{\"eyebrow\":\"Savings & tax deduction\",\"h2\":\"เลือกประเภทแบบประกันไทยประกันชีวิต\",\"lead\":\"\",\"sidebarLabel\":\"\"}','2026-05-26 14:21:03'),(37,'home','testimonials','เสียงตอบรับจากลูกค้าตัวจริง',1,6,'{\"eyebrow\":\"\",\"h2\":\"เสียงตอบรับจากลูกค้าตัวจริง\",\"lead\":\"\"}','2026-05-26 14:21:03'),(38,'home','homeArticles','ข่าวสารและบทความ',1,7,'{\"eyebrow\":\"Hot New\",\"h2\":\"ข่าวสารและบทความ\",\"lead\":\"บทความและข่าวสารเกี่ยวกับประกันชีวิต สุขภาพ การออม และการวางแผนทางการเงิน — อ่านก่อนตัดสินใจเลือกแผน\",\"moreText\":\"ดูบทความทั้งหมด\",\"moreHref\":\"articles\\/life-insurance-by-age.html\"}','2026-05-26 14:21:03'),(39,'home','homeCareers','แนะนำอาชีพตัวแทนไทยประกันชีวิต',1,8,'{\"eyebrow\":\"Career\",\"h2\":\"แนะนำอาชีพตัวแทนไทยประกันชีวิต\",\"lead\":\"อาชีพที่ปรึกษาประกันชีวิตและการเงิน — รายได้ตามผลงาน ทำงานยืดหยุ่น และมีทีมสนับสนุนจากไทยประกันชีวิต\",\"moreText\":\"ดูทั้งหมด 9 เรื่อง\",\"moreHref\":\"careers\\/why-advisor.html\"}','2026-05-26 14:21:03'),(40,'home','ctaBand','ไม่แน่ใจว่าควรเริ่มจากแผนไหน ให้ทีมสาขาบางนาช่วยวิเคราะห์ก่อนตัดสินใจ',1,9,'{\"eyebrow\":\"Free consultation\",\"h2\":\"ไม่แน่ใจว่าควรเริ่มจากแผนไหน ให้ทีมสาขาบางนาช่วยวิเคราะห์ก่อนตัดสินใจ\",\"copy\":\"\",\"buttonText\":\"ไปหน้าติดต่อ\",\"buttonHref\":\"contact.html\"}','2026-05-26 14:21:03'),(41,'news','hero','ข่าวสารและบทความ',1,0,'{\"eyebrow\":\"News & Articles\",\"h1\":\"ข่าวสารและบทความ\",\"copy\":\"รวมบทความและข่าวสารเกี่ยวกับประกันชีวิต สุขภาพ การออม ลดหย่อนภาษี และการวางแผนทางการเงิน\"}','2026-05-26 14:21:03'),(42,'careers','hero','ปลดล็อกรายได้ที่ไม่มีเพดาน พร้อมอิสระในการใช้ชีวิตที่คุณออกแบบเองได้',1,0,'{\"h1\":\"ปลดล็อกรายได้ที่ไม่มีเพดาน พร้อมอิสระในการใช้ชีวิตที่คุณออกแบบเองได้\",\"copy\":\"เหนื่อยไหม? กับการทุ่มเททำงานหนักแต่รายได้ยังคงถูกจำกัดด้วยฐานเงินเดือนเดิม ๆ... มาร่วมเป็น “ที่ปรึกษาประกันชีวิต” อาชีพที่จะเปลี่ยนให้คุณเป็นเจ้านายตัวเอง!\",\"imageSrc\":\"assets\\/career\\/career-hero.png\"}','2026-05-26 14:21:03'),(43,'contact','hero','คุยกับทีมไทยประกันชีวิต สาขาบางนา',1,0,'{\"eyebrow\":\"Contact Wealth Life Insure\",\"h1\":\"คุยกับทีมไทยประกันชีวิต สาขาบางนา\",\"copy\":\"ติดต่อเพื่อขอคำปรึกษาเรื่องเลกาซี ฟิต แคร์, คุ้มธนกิจ, Health Fit DD, ทีแอลแพลน และมันนี่ ฟิต เวลท์ตี้ หรือฝากข้อมูลให้ทีมงานติดต่อกลับ\"}','2026-05-26 14:21:03'),(44,'about','hero','ทีมงาน FSEG Wealth ตัวแทนไทยประกันชีวิต',1,0,'{\"eyebrow\":\"Thai Life Insurance Bangna\",\"h1\":\"ทีมงาน FSEG Wealth ตัวแทนไทยประกันชีวิต\",\"lead\":\"Wealth Life Insure ดูแลโดยทีมผู้บริหารศูนย์และผู้บริหารหน่วยไทยประกันชีวิต สาขาบางนา ให้คำแนะนำทั้งประกันชีวิต สุขภาพ ออมทรัพย์ มรดก และลดหย่อนภา