INSERT INTO `seo_meta` (`id`, `page_key`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`, `canonical_url`, `robots_index`, `slug`, `updated_at`) VALUES (11,'home','Wealth Life Insure | ไทยประกันชีวิต สาขาบางนา','Wealth Life Insure ที่ปรึกษาไทยประกันชีวิต สาขาบางนา ดูแลประกันชีวิต สุขภาพ ออมทรัพย์ บำนาญ และลดหย่อนภาษี',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(12,'news','ข่าวสารและบทความ | Wealth Life Insure','ข่าวสารและบทความ Wealth Life Insure เรื่องประกันชีวิต สุขภาพ ออมทรัพย์ และการวางแผนทางการเงิน',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(13,'careers','แนะนำอาชีพตัวแทนไทยประกันชีวิต | Wealth Life Insure','แนะนำอาชีพตัวแทนไทยประกันชีวิต รายได้ไม่มีเพดาน อบรมฟรี และทีมสนับสนุนจาก Wealth Life Insure สาขาบางนา',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(14,'contact','ติดต่อเรา | Wealth Life Insure','ติดต่อ แต้ม และ เอ ทีมไทยประกันชีวิต สาขาบางนา เพื่อขอคำปรึกษาแบบประกันและวางแผนความคุ้มครอง',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(15,'about','ทีมงาน FSEG Wealth ตัวแทนไทยประกันชีวิต | Wealth Life Insure','ทีมงาน FSEG Wealth ตัวแทนไทยประกันชีวิต สาขาบางนา ให้คำแนะนำประกันชีวิต สุขภาพ ออมทรัพย์ มรดก และลดหย่อนภาษี',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(16,'insurance','แบบประกัน | Wealth Life Insure','รวมแบบประกันไทยประกันชีวิต เลกาซี ฟิต แคร์ คุ้มธนกิจ Health Fit DD ทีแอลแพลน และมันนี่ ฟิต เวลท์ตี้',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(17,'lifeInsurance','ประกันชีวิตและมรดก | Wealth Life Insure','รายละเอียดแบบประกันชีวิต เลกาซี ฟิต แคร์ 99/10 และคุ้มธนกิจ 99/20 จากไทยประกันชีวิต',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(18,'healthInsurance','Health Fit DD | Wealth Life Insure','รายละเอียดประกันสุขภาพ Health Fit DD เหมาจ่ายสูงสุด 30 ล้านบาท ครอบคลุมผู้ป่วยในและผู้ป่วยนอก',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03'),(19,'savingsRetirement','ทีแอลแพลน และมันนี่ ฟิต เวลท์ตี้ | Wealth Life Insure','รายละเอียดแผนออมทรัพย์ ทีแอลแพลน และมันนี่ ฟิต เวลท์ตี้ 18/4 สำหรับวางแผนเงินออมและลดหย่อนภาษี',NULL,NULL,NULL,1,NULL,'2026-05-26 14:21:03');
