INSERT INTO `careers` (`id`, `slug`, `title`, `excerpt`, `body_html`, `cover_image`, `eyebrow`, `hero_lead`, `hero_image`, `status`, `is_featured`, `published_at`, `seo_title`, `seo_description`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'why-advisor','อาชีพที่ปรึกษาประกันชีวิต ดีอย่างไร?','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน','<p>อาชีพที่ปรึกษาประกันชีวิตไม่ใช่แค่การขาย แต่คือการช่วยลูกค้าวางแผนความคุ้มครอง การออม และการส่งต่อความมั่นใจให้ครอบครัว</p>\n          <p>คุณได้เรียนรู้ผลิตภัณฑ์ใหม่ ๆ อยู่เสมอ พัฒนาทักษะการสื่อสาร และสร้างเครือข่ายความสัมพันธ์ระยะยาวกับลูกค้า</p>\n          <p>หากชอบความยืดหยุ่นและอยากเป็นเจ้าของเวลาตัวเอง อาชีพนี้เปิดโอกาสให้คุณออกแบบชีวิตการทำงานได้มากกว่าอาชีพประจำทั่วไป</p>','assets/career/covers/why-advisor.jpg','แนะนำอาชีพ','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',NULL,'published',0,'2026-05-26 14:21:03',NULL,'อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',0,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(2,'unlimited-income','รายได้ไม่มีเพดาน สร้างอิสระทางการเงิน','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ','<p>ตัวแทนประกันชีวิตมีโครงสร้างรายได้ที่ผูกกับผลงานและการบริหารทีม ไม่ได้ถูกจำกัดด้วยตำแหน่งเพียงอย่างเดียว</p>\n          <p>ยิ่งสร้างความไว้วางใจกับลูกค้าและดูแลหลังการขายได้ดี ยิ่งมีโอกาสสร้างรายได้ระยะยาวจากการต่ออายุและการแนะนำ</p>\n          <p>การวางแผนรายได้และงบประมาณส่วนตัวอย่างจริงจัง จะช่วยให้คุณใช้ศักยภาพของอาชีพนี้ได้เต็มที่</p>','assets/career/covers/unlimited-income.jpg','แนะนำอาชีพ','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',NULL,'published',0,'2026-05-26 14:21:03',NULL,'รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',1,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(3,'flexible-life','ทำงานยืดหยุ่น ออกแบบชีวิตได้เอง','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน','<p>คุณสามารถเลือกช่วงเวลาพบลูกค้า ทำงานออนไลน์ หรือพัฒนาทีมได้ตามเป้าหมายชีวิต</p>\n          <p>ความยืดหยุ่นไม่ได้หมายถึงไม่ต้องมีวินัย แต่หมายถึงคุณเป็นคนกำหนดกรอบการทำงานของตัวเอง</p>\n          <p>หลายคนเริ่มจากงาน part-time แล้วค่อยขยายเป็นอาชีพหลักเมื่อมั่นใจในระบบและทักษะ</p>','assets/career/covers/flexible-life.jpg','แนะนำอาชีพ','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',NULL,'published',0,'2026-05-26 14:21:03',NULL,'จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',2,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(4,'training','อบรมและพัฒนาทักษะจากบริษัท','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ','<p>มีหลักสูตรตั้งแต่พื้นฐานผลิตภัณฑ์ การวางแผนการเงิน ไปจนถึงการบริหารทีม</p>\n          <p>การอบรมอย่างต่อเนื่องช่วยให้คุณอัปเดตความรู้ตามกฎหมาย ผลิตภัณฑ์ใหม่ และแนวทางการให้คำปรึกษา</p>\n          <p>ทีม Wealth Life Insure สาขาบางนา พร้อมแชร์ประสบการณ์จริงและช่วยประคองในช่วงแรกของอาชีพ</p>','assets/career/covers/training.jpg','แนะนำอาชีพ','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',NULL,'published',0,'2026-05-26 14:21:03',NULL,'ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',3,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(5,'team-support','มีทีมพี่เลี้ยงและระบบสนับสนุน','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม','<p>ระบบสายงานช่วยให้คุณมีที่ปรึกษาเมื่อเจอเคสซับซ้อน หรือต้องการแนวทางในการเสนอแผน</p>\n          <p>การทำงานเป็นทีมช่วยลดความกดดันและเพิ่มโอกาสเรียนรู้จากประสบการณ์ของรุ่นพี่</p>\n          <p>ลูกค้าได้บริการต่อเนื่องทั้งก่อนและหลังทำกรมธรรม์ ซึ่งสร้างความมั่นใจให้ตัวแทนทุกคน</p>','assets/career/covers/team-support.jpg','แนะนำอาชีพ','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',NULL,'published',0,'2026-05-26 14:21:03',NULL,'ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',4,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(6,'how-to-start','เริ่มต้นอาชีพตัวแทนอย่างไร','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน','<p>เริ่มจากทำความเข้าใจโครงสร้างรายได้ ภาระผูกพัน และแผนพัฒนาตนเองใน 1–3 ปีแรก</p>\n          <p>เตรียมเอกสารส่วนตัว ประวัติการศึกษา และเวลาที่สามารถอบรมได้</p>\n          <p>พูดคุยกับทีมสาขาบางนาเพื่อรับคำแนะนำว่าเส้นทางไหนเหมาะกับเป้าหมายของคุณ</p>','assets/career/covers/how-to-start.jpg','แนะนำอาชีพ','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',NULL,'published',0,'2026-05-26 14:21:03',NULL,'ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',5,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(7,'who-fits','ใครเหมาะกับอาชีพตัวแทนประกันชีวิต','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม','<p>คนที่ชอบฟัง ชอบช่วยเหลือ และมีวินัยในการติดตามงาน มักปรับตัวได้ดี</p>\n          <p>ไม่จำเป็นต้องเคยขายมาก่อน แต่ต้องเปิดใจเรียนรู้และยอมรับการโค้ชจากพี่เลี้ยง</p>\n          <p>ความซื่อสัตย์และการดูแลลูกค้าหลังการขาย คือหัวใจสำคัญของอาชีพระยะยาว</p>','assets/career/covers/who-fits.jpg','แนะนำอาชีพ','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',NULL,'published',0,'2026-05-26 14:21:03',NULL,'บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',6,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(8,'career-path','เส้นทางความก้าวหน้าในอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต','<p>อาชีพตัวแทนมีเส้นทางเติบโตทั้งด้านผลงานขาย การบริหารทีม และการพัฒนาผู้คน</p>\n          <p>การตั้งเป้าหมายรายปีและทบทวนทุกไตรมาส ช่วยให้เห็นภาพความก้าวหน้าชัดขึ้น</p>\n          <p>หลายผู้บริหารเริ่มจากจุดเล็ก ๆ ด้วยความสม่ำเสมอและการดูแลลูกค้าอย่างจริงใจ</p>','assets/career/covers/career-path.jpg','แนะนำอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',NULL,'published',0,'2026-05-26 14:21:03',NULL,'จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',7,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(9,'faq','คำถามที่พบบ่อยก่อนตัดสินใจ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ','<p>ต้องใช้เงินทุนเริ่มต้นเท่าไร? ใช้เวลากี่ชั่วโมงต่อสัปดาห์? คำตอบขึ้นกับเป้าหมายและแผนที่คุณเลือก</p>\n          <p>รายได้ไม่ได้มาในชั่วข้ามคืน แต่สร้างได้เมื่อมีระบบ มีพี่เลี้ยง และทำอย่างสม่ำเสมอ</p>\n          <p>ปรึกษาทีม Wealth Life Insure สาขาบางนา ได้ฟรีเพื่อช่วยตอบข้อสงสัยก่อนตัดสินใจ</p>','assets/career/covers/faq.jpg','แนะนำอาชีพ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',NULL,'published',0,'2026-05-26 14:21:03',NULL,'รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',8,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(19,'why-advisor-1','อาชีพที่ปรึกษาประกันชีวิต ดีอย่างไร?','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน','<p>อาชีพที่ปรึกษาประกันชีวิตไม่ใช่แค่การขาย แต่คือการช่วยลูกค้าวางแผนความคุ้มครอง การออม และการส่งต่อความมั่นใจให้ครอบครัว</p>\n          <p>คุณได้เรียนรู้ผลิตภัณฑ์ใหม่ ๆ อยู่เสมอ พัฒนาทักษะการสื่อสาร และสร้างเครือข่ายความสัมพันธ์ระยะยาวกับลูกค้า</p>\n          <p>หากชอบความยืดหยุ่นและอยากเป็นเจ้าของเวลาตัวเอง อาชีพนี้เปิดโอกาสให้คุณออกแบบชีวิตการทำงานได้มากกว่าอาชีพประจำทั่วไป</p>','assets/career/covers/why-advisor.jpg','แนะนำอาชีพ','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',NULL,'published',0,'2026-05-29 01:02:21',NULL,'อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',0,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(20,'unlimited-income-1','รายได้ไม่มีเพดาน สร้างอิสระทางการเงิน','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ','<p>ตัวแทนประกันชีวิตมีโครงสร้างรายได้ที่ผูกกับผลงานและการบริหารทีม ไม่ได้ถูกจำกัดด้วยตำแหน่งเพียงอย่างเดียว</p>\n          <p>ยิ่งสร้างความไว้วางใจกับลูกค้าและดูแลหลังการขายได้ดี ยิ่งมีโอกาสสร้างรายได้ระยะยาวจากการต่ออายุและการแนะนำ</p>\n          <p>การวางแผนรายได้และงบประมาณส่วนตัวอย่างจริงจัง จะช่วยให้คุณใช้ศักยภาพของอาชีพนี้ได้เต็มที่</p>','assets/career/covers/unlimited-income.jpg','แนะนำอาชีพ','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',NULL,'published',0,'2026-05-29 01:02:21',NULL,'รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',1,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(21,'flexible-life-1','ทำงานยืดหยุ่น ออกแบบชีวิตได้เอง','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน','<p>คุณสามารถเลือกช่วงเวลาพบลูกค้า ทำงานออนไลน์ หรือพัฒนาทีมได้ตามเป้าหมายชีวิต</p>\n          <p>ความยืดหยุ่นไม่ได้หมายถึงไม่ต้องมีวินัย แต่หมายถึงคุณเป็นคนกำหนดกรอบการทำงานของตัวเอง</p>\n          <p>หลายคนเริ่มจากงาน part-time แล้วค่อยขยายเป็นอาชีพหลักเมื่อมั่นใจในระบบและทักษะ</p>','assets/career/covers/flexible-life.jpg','แนะนำอาชีพ','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',NULL,'published',0,'2026-05-29 01:02:21',NULL,'จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',2,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(22,'training-1','อบรมและพัฒนาทักษะจากบริษัท','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ','<p>มีหลักสูตรตั้งแต่พื้นฐานผลิตภัณฑ์ การวางแผนการเงิน ไปจนถึงการบริหารทีม</p>\n          <p>การอบรมอย่างต่อเนื่องช่วยให้คุณอัปเดตความรู้ตามกฎหมาย ผลิตภัณฑ์ใหม่ และแนวทางการให้คำปรึกษา</p>\n          <p>ทีม Wealth Life Insure สาขาบางนา พร้อมแชร์ประสบการณ์จริงและช่วยประคองในช่วงแรกของอาชีพ</p>','assets/career/covers/training.jpg','แนะนำอาชีพ','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',NULL,'published',0,'2026-05-29 01:02:21',NULL,'ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',3,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(23,'team-support-1','มีทีมพี่เลี้ยงและระบบสนับสนุน','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม','<p>ระบบสายงานช่วยให้คุณมีที่ปรึกษาเมื่อเจอเคสซับซ้อน หรือต้องการแนวทางในการเสนอแผน</p>\n          <p>การทำงานเป็นทีมช่วยลดความกดดันและเพิ่มโอกาสเรียนรู้จากประสบการณ์ของรุ่นพี่</p>\n          <p>ลูกค้าได้บริการต่อเนื่องทั้งก่อนและหลังทำกรมธรรม์ ซึ่งสร้างความมั่นใจให้ตัวแทนทุกคน</p>','assets/career/covers/team-support.jpg','แนะนำอาชีพ','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',NULL,'published',0,'2026-05-29 01:02:21',NULL,'ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',4,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(24,'how-to-start-1','เริ่มต้นอาชีพตัวแทนอย่างไร','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน','<p>เริ่มจากทำความเข้าใจโครงสร้างรายได้ ภาระผูกพัน และแผนพัฒนาตนเองใน 1–3 ปีแรก</p>\n          <p>เตรียมเอกสารส่วนตัว ประวัติการศึกษา และเวลาที่สามารถอบรมได้</p>\n          <p>พูดคุยกับทีมสาขาบางนาเพื่อรับคำแนะนำว่าเส้นทางไหนเหมาะกับเป้าหมายของคุณ</p>','assets/career/covers/how-to-start.jpg','แนะนำอาชีพ','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',NULL,'published',0,'2026-05-29 01:02:21',NULL,'ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',5,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(25,'who-fits-1','ใครเหมาะกับอาชีพตัวแทนประกันชีวิต','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม','<p>คนที่ชอบฟัง ชอบช่วยเหลือ และมีวินัยในการติดตามงาน มักปรับตัวได้ดี</p>\n          <p>ไม่จำเป็นต้องเคยขายมาก่อน แต่ต้องเปิดใจเรียนรู้และยอมรับการโค้ชจากพี่เลี้ยง</p>\n          <p>ความซื่อสัตย์และการดูแลลูกค้าหลังการขาย คือหัวใจสำคัญของอาชีพระยะยาว</p>','assets/career/covers/who-fits.jpg','แนะนำอาชีพ','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',NULL,'published',0,'2026-05-29 01:02:21',NULL,'บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',6,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(26,'career-path-1','เส้นทางความก้าวหน้าในอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต','<p>อาชีพตัวแทนมีเส้นทางเติบโตทั้งด้านผลงานขาย การบริหารทีม และการพัฒนาผู้คน</p>\n          <p>การตั้งเป้าหมายรายปีและทบทวนทุกไตรมาส ช่วยให้เห็นภาพความก้าวหน้าชัดขึ้น</p>\n          <p>หลายผู้บริหารเริ่มจากจุดเล็ก ๆ ด้วยความสม่ำเสมอและการดูแลลูกค้าอย่างจริงใจ</p>','assets/career/covers/career-path.jpg','แนะนำอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',NULL,'published',0,'2026-05-29 01:02:21',NULL,'จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',7,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(27,'faq-1','คำถามที่พบบ่อยก่อนตัดสินใจ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ','<p>ต้องใช้เงินทุนเริ่มต้นเท่าไร? ใช้เวลากี่ชั่วโมงต่อสัปดาห์? คำตอบขึ้นกับเป้าหมายและแผนที่คุณเลือก</p>\n          <p>รายได้ไม่ได้มาในชั่วข้ามคืน แต่สร้างได้เมื่อมีระบบ มีพี่เลี้ยง และทำอย่างสม่ำเสมอ</p>\n          <p>ปรึกษาทีม Wealth Life Insure สาขาบางนา ได้ฟรีเพื่อช่วยตอบข้อสงสัยก่อนตัดสินใจ</p>','assets/career/covers/faq.jpg','แนะนำอาชีพ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',NULL,'published',0,'2026-05-29 01:02:21',NULL,'รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',8,'2026-05-29 01:02:21','2026-05-29 01:02:21'),(28,'why-advisor-2','อาชีพที่ปรึกษาประกันชีวิต ดีอย่างไร?','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน','<p>อาชีพที่ปรึกษาประกันชีวิตไม่ใช่แค่การขาย แต่คือการช่วยลูกค้าวางแผนความคุ้มครอง การออม และการส่งต่อความมั่นใจให้ครอบครัว</p>\n          <p>คุณได้เรียนรู้ผลิตภัณฑ์ใหม่ ๆ อยู่เสมอ พัฒนาทักษะการสื่อสาร และสร้างเครือข่ายความสัมพันธ์ระยะยาวกับลูกค้า</p>\n          <p>หากชอบความยืดหยุ่นและอยากเป็นเจ้าของเวลาตัวเอง อาชีพนี้เปิดโอกาสให้คุณออกแบบชีวิตการทำงานได้มากกว่าอาชีพประจำทั่วไป</p>','assets/career/covers/why-advisor.jpg','แนะนำอาชีพ','อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',NULL,'published',0,'2026-05-29 01:11:42',NULL,'อาชีพที่ปรึกษาประกันชีวิตและการเงิน เป็นอาชีพที่มีเสน่ห์และตอบโจทย์คนที่ชอบคุยกับคน ชอบช่วยวางแผน และอยากมีรายได้ตามผลงาน',0,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(29,'unlimited-income-2','รายได้ไม่มีเพดาน สร้างอิสระทางการเงิน','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ','<p>ตัวแทนประกันชีวิตมีโครงสร้างรายได้ที่ผูกกับผลงานและการบริหารทีม ไม่ได้ถูกจำกัดด้วยตำแหน่งเพียงอย่างเดียว</p>\n          <p>ยิ่งสร้างความไว้วางใจกับลูกค้าและดูแลหลังการขายได้ดี ยิ่งมีโอกาสสร้างรายได้ระยะยาวจากการต่ออายุและการแนะนำ</p>\n          <p>การวางแผนรายได้และงบประมาณส่วนตัวอย่างจริงจัง จะช่วยให้คุณใช้ศักยภาพของอาชีพนี้ได้เต็มที่</p>','assets/career/covers/unlimited-income.jpg','แนะนำอาชีพ','รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',NULL,'published',0,'2026-05-29 01:11:42',NULL,'รายได้จากผลงานและการดูแลลูกค้าอย่างต่อเนื่อง ช่วยให้คุณก้าวข้ามขีดจำกัดของฐานเงินเดือนเดิม ๆ',1,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(30,'flexible-life-2','ทำงานยืดหยุ่น ออกแบบชีวิตได้เอง','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน','<p>คุณสามารถเลือกช่วงเวลาพบลูกค้า ทำงานออนไลน์ หรือพัฒนาทีมได้ตามเป้าหมายชีวิต</p>\n          <p>ความยืดหยุ่นไม่ได้หมายถึงไม่ต้องมีวินัย แต่หมายถึงคุณเป็นคนกำหนดกรอบการทำงานของตัวเอง</p>\n          <p>หลายคนเริ่มจากงาน part-time แล้วค่อยขยายเป็นอาชีพหลักเมื่อมั่นใจในระบบและทักษะ</p>','assets/career/covers/flexible-life.jpg','แนะนำอาชีพ','จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',NULL,'published',0,'2026-05-29 01:11:42',NULL,'จัดตารางนัดหมาย ทำงาน และพัฒนาตัวเองได้ตามไลฟ์สไตล์ — เหมาะกับคนที่อยากบาลานซ์ครอบครัวและงาน',2,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(31,'training-2','อบรมและพัฒนาทักษะจากบริษัท','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ','<p>มีหลักสูตรตั้งแต่พื้นฐานผลิตภัณฑ์ การวางแผนการเงิน ไปจนถึงการบริหารทีม</p>\n          <p>การอบรมอย่างต่อเนื่องช่วยให้คุณอัปเดตความรู้ตามกฎหมาย ผลิตภัณฑ์ใหม่ และแนวทางการให้คำปรึกษา</p>\n          <p>ทีม Wealth Life Insure สาขาบางนา พร้อมแชร์ประสบการณ์จริงและช่วยประคองในช่วงแรกของอาชีพ</p>','assets/career/covers/training.jpg','แนะนำอาชีพ','ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',NULL,'published',0,'2026-05-29 01:11:42',NULL,'ไทยประกันชีวิตมีหลักสูตรอบรม ระบบพี่เลี้ยง และเครื่องมือดิจิทัล ช่วยให้คนใหม่เริ่มได้อย่างมั่นใจ',3,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(32,'team-support-2','มีทีมพี่เลี้ยงและระบบสนับสนุน','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม','<p>ระบบสายงานช่วยให้คุณมีที่ปรึกษาเมื่อเจอเคสซับซ้อน หรือต้องการแนวทางในการเสนอแผน</p>\n          <p>การทำงานเป็นทีมช่วยลดความกดดันและเพิ่มโอกาสเรียนรู้จากประสบการณ์ของรุ่นพี่</p>\n          <p>ลูกค้าได้บริการต่อเนื่องทั้งก่อนและหลังทำกรมธรรม์ ซึ่งสร้างความมั่นใจให้ตัวแทนทุกคน</p>','assets/career/covers/team-support.jpg','แนะนำอาชีพ','ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',NULL,'published',0,'2026-05-29 01:11:42',NULL,'ไม่ได้ทำงานคนเดียว — มีผู้บริหารศูนย์ ผู้บริหารหน่วย และทีมที่ช่วยประสานงานเอกสารและเคลม',4,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(33,'how-to-start-2','เริ่มต้นอาชีพตัวแทนอย่างไร','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน','<p>เริ่มจากทำความเข้าใจโครงสร้างรายได้ ภาระผูกพัน และแผนพัฒนาตนเองใน 1–3 ปีแรก</p>\n          <p>เตรียมเอกสารส่วนตัว ประวัติการศึกษา และเวลาที่สามารถอบรมได้</p>\n          <p>พูดคุยกับทีมสาขาบางนาเพื่อรับคำแนะนำว่าเส้นทางไหนเหมาะกับเป้าหมายของคุณ</p>','assets/career/covers/how-to-start.jpg','แนะนำอาชีพ','ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',NULL,'published',0,'2026-05-29 01:11:42',NULL,'ขั้นตอนเริ่มต้น เอกสารที่ต้องเตรียม และสิ่งที่ควรถามก่อนตัดสินใจสมัครเป็นตัวแทน',5,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(34,'who-fits-2','ใครเหมาะกับอาชีพตัวแทนประกันชีวิต','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม','<p>คนที่ชอบฟัง ชอบช่วยเหลือ และมีวินัยในการติดตามงาน มักปรับตัวได้ดี</p>\n          <p>ไม่จำเป็นต้องเคยขายมาก่อน แต่ต้องเปิดใจเรียนรู้และยอมรับการโค้ชจากพี่เลี้ยง</p>\n          <p>ความซื่อสัตย์และการดูแลลูกค้าหลังการขาย คือหัวใจสำคัญของอาชีพระยะยาว</p>','assets/career/covers/who-fits.jpg','แนะนำอาชีพ','บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',NULL,'published',0,'2026-05-29 01:11:42',NULL,'บุคลิกและทักษะแบบไหนที่มักประสบความสำเร็จในอาชีพนี้ — และสิ่งที่ควรพิจารณาก่อนเริ่ม',6,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(35,'career-path-2','เส้นทางความก้าวหน้าในอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต','<p>อาชีพตัวแทนมีเส้นทางเติบโตทั้งด้านผลงานขาย การบริหารทีม และการพัฒนาผู้คน</p>\n          <p>การตั้งเป้าหมายรายปีและทบทวนทุกไตรมาส ช่วยให้เห็นภาพความก้าวหน้าชัดขึ้น</p>\n          <p>หลายผู้บริหารเริ่มจากจุดเล็ก ๆ ด้วยความสม่ำเสมอและการดูแลลูกค้าอย่างจริงใจ</p>','assets/career/covers/career-path.jpg','แนะนำอาชีพ','จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',NULL,'published',0,'2026-05-29 01:11:42',NULL,'จากตัวแทนใหม่สู่ผู้บริหารหน่วยและศูนย์ — โครงสร้างที่ชัดเจนช่วยวางแผนอนาคต',7,'2026-05-29 01:11:42','2026-05-29 01:11:42'),(36,'faq-2','คำถามที่พบบ่อยก่อนตัดสินใจ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ','<p>ต้องใช้เงินทุนเริ่มต้นเท่าไร? ใช้เวลากี่ชั่วโมงต่อสัปดาห์? คำตอบขึ้นกับเป้าหมายและแผนที่คุณเลือก</p>\n          <p>รายได้ไม่ได้มาในชั่วข้ามคืน แต่สร้างได้เมื่อมีระบบ มีพี่เลี้ยง และทำอย่างสม่ำเสมอ</p>\n          <p>ปรึกษาทีม Wealth Life Insure สาขาบางนา ได้ฟรีเพื่อช่วยตอบข้อสงสัยก่อนตัดสินใจ</p>','assets/career/covers/faq.jpg','แนะนำอาชีพ','รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',NULL,'published',0,'2026-05-29 01:11:42',NULL,'รวมคำถามเรื่องรายได้ ค่าใช้จ่ายเริ่มต้น เวลา และความเสี่ยงที่มักถามก่อนเข้าสู่อาชีพ',8,'2026-05-29 01:11:42','2026-05-29 01:11:42');
