INSERT INTO `insurance_plans` (`id`, `category_id`, `filter_tag`, `name`, `slug`, `short_description`, `full_description`, `highlights`, `image_path`, `price_from`, `insurer_name`, `pdf_path`, `link_url`, `contact_button_text`, `is_featured`, `is_hot`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES (1,NULL,'life','เลกาซี ฟิต แคร์ 99/10','เลกาซ-ฟ-ต-แคร-99-10','ผสานความคุ้มครองชีวิตและสุขภาพ เปลี่ยนวงเงินคุ้มครองเป็นค่ารักษาพยาบาลในวัยเกษียณได้ และช่วยสร้างกองทุนมรดก','',NULL,'assets/แผนประกัน/เลกาซี ฟิต แคร์ 99-10.png','','ไทยประกันชีวิต','','life-insurance.html','ปรึกษาแผนนี้',1,0,1,0,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 20:33:11'),(2,NULL,'life','คุ้มธนกิจ 99/20 (Nn)','ค-มธนก-จ-99-20-nn','ประกันชีวิตเพื่อสร้างหลักประกันและกองทุนมรดก ชำระเบี้ย 20 ปี คุ้มครองถึงอายุ 99 ปี และใช้ลดหย่อนภาษีได้',NULL,NULL,'assets/แผนประกัน/คุ้มธนกิจ 99-20 (Nn).png',NULL,'ไทยประกันชีวิต',NULL,'life-insurance.html','ปรึกษาแผนนี้',1,0,1,1,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(3,NULL,'health','Health Fit DD','health-fit-dd','ประกันสุขภาพเหมาจ่าย คุ้มครองสูงสุด 30 ล้านบาท ครอบคลุมผู้ป่วยใน ผู้ป่วยนอก และออกแบบ Deductible ได้',NULL,NULL,'assets/แผนประกัน/Health Fit DD.png',NULL,'ไทยประกันชีวิต',NULL,'health-insurance.html','ปรึกษาแผนนี้',1,0,1,2,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(4,NULL,'savings','ทีแอลแพลน','ท-แอลแพลน','อิสระแห่งการออมเพื่ออนาคต เลือกได้ทั้ง 20/10 และ 20/15 รับเงินก้อนเมื่อครบกำหนดสัญญา 150%',NULL,NULL,'assets/แผนประกัน/ทีแอลแพลน.png',NULL,'ไทยประกันชีวิต',NULL,'savings-retirement.html','ปรึกษาแผนนี้',1,0,1,3,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(5,NULL,'savings','มันนี่ ฟิต เวลท์ตี้ 18/4','ม-นน-ฟ-ต-เวลท-ต-18-4','จ่ายเบี้ยสั้น 4 ปี คุ้มครอง 18 ปี มีเงินคืนทุกปี มีโอกาสรับเงินปันผล และใช้ลดหย่อนภาษีได้ตามเกณฑ์',NULL,NULL,'assets/แผนประกัน/มันนี่ ฟิต เวลท์ตี้ 18-4.png',NULL,'ไทยประกันชีวิต',NULL,'savings-retirement.html','ปรึกษาแผนนี้',1,0,1,4,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(6,NULL,'life','เลือกประกันชีวิตตามช่วงวัย ควรดูอะไรบ้าง','เล-อกประก-นช-ว-ตตามช-วงว-ย-ควรด-อะไรบ-าง','แยกความต้องการตามวัยทำงาน วัยมีครอบครัว และวัยใกล้เกษียณ พร้อมจุดที่ควรถามที่ปรึกษาก่อนทำกรมธรรม์',NULL,NULL,'assets/ภาพบทความ/272d35ea-4dcd-4a2c-93df-47a5db903fcb.png',NULL,'ไทยประกันชีวิต',NULL,'articles/life-insurance-by-age.html','ปรึกษาแผนนี้',1,0,1,5,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(7,NULL,'life','วางแผนมรดกด้วยประกันชีวิต เริ่มจากอะไร','วางแผนมรดกด-วยประก-นช-ว-ต-เร-มจากอะไร','ทำความเข้าใจการสร้างหลักประกันให้ครอบครัว การจัดสรรผลประโยชน์ และแผนที่ผสานความคุ้มครองกับออมทรัพย์',NULL,NULL,'assets/ภาพบทความ/c2901b59-0ff2-456b-9654-5e107de8323e.png',NULL,'ไทยประกันชีวิต',NULL,'articles/legacy-planning.html','ปรึกษาแผนนี้',1,0,1,6,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(8,NULL,'health','Health Fit DD คืออะไร เหมาะกับใคร','health-fit-dd-ค-ออะไร-เหมาะก-บใคร','ประกันสุขภาพเหมาจ่าย คุ้มครองสูงสุด 30 ล้านบาท ครอบคลุมผู้ป่วยใน ผู้ป่วยนอก และออกแบบ Deductible ได้',NULL,NULL,'assets/ภาพบทความ/370ac54d-68e8-4936-b8c7-602ffe49c0ed.png',NULL,'ไทยประกันชีวิต',NULL,'articles/health-fit-dd.html','ปรึกษาแผนนี้',1,0,1,7,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(9,NULL,'health','ประกันสุขภาพเหมาจ่าย vs ชดเชยรายได้ ต่างกันอย่างไร','ประก-นส-ขภาพเหมาจ-าย-vs-ชดเชยรายได-ต-างก-นอย-างไร','เปรียบเทียบแนวคิดความคุ้มครอง ข้อดีข้อจำกัด และวิธีเลือกให้เหมาะกับพฤติกรรมการใช้บริการรักษา',NULL,NULL,'assets/ภาพบทความ/db025e47-08c1-4c01-a0ab-e8273b9e2c5a.png',NULL,'ไทยประกันชีวิต',NULL,'articles/health-lump-sum-vs-income.html','ปรึกษาแผนนี้',1,0,1,8,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(10,NULL,'savings','ลดหย่อนภาษีด้วยประกันออมทรัพย์ ควรรู้อะไรก่อนตัดสินใจ','ลดหย-อนภาษ-ด-วยประก-นออมทร-พย-ควรร-อะไรก-อนต-ดส-นใจ','สรุปแนวคิดการใช้สิทธิลดหย่อน ข้อจำกัดที่มักพลาด และการจับคู่แผนกับเป้าหมายระยะยาว',NULL,NULL,'assets/ภาพบทความ/052b9a4c-a49e-489a-92da-bc608accaa55.png',NULL,'ไทยประกันชีวิต',NULL,'articles/tax-savings-insurance.html','ปรึกษาแผนนี้',1,0,1,9,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(11,NULL,'savings','เกษียณอย่างมั่นใจด้วยทีแอลแพลน และมันนี่ ฟิต เวลท์ตี้','เกษ-ยณอย-างม-นใจด-วยท-แอลแพลน-และม-นน-ฟ-ต-เวลท-ต','เปรียบเทียบแนวทางออมระยะสั้น–กลาง เงินคืนรายปี และการสร้างกองทุนเกษียณแบบมีแผน',NULL,NULL,'assets/ภาพบทความ/b8213c41-6601-44ec-867c-14b4844373a5.png',NULL,'ไทยประกันชีวิต',NULL,'articles/retirement-tl-money-fit.html','ปรึกษาแผนนี้',1,0,1,10,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(12,NULL,'','เตรียมตัวก่อนพบที่ปรึกษาประกัน 5 ข้อที่ควรเตรียม','เตร-ยมต-วก-อนพบท-ปร-กษาประก-น-5-ข-อท-ควรเตร-ยม','รวมข้อมูลสุขภาพ งบประมาณ เป้าหมายครอบครัว และแผนที่เคยมี เพื่อให้การปรึกษาครั้งแรกได้คำตอบชัดขึ้น',NULL,NULL,'assets/ภาพบทความ/3de0808d-8302-49a6-a6f1-16fab3ed74e3.png',NULL,'ไทยประกันชีวิต',NULL,'articles/prepare-for-advisor.html','ปรึกษาแผนนี้',1,0,1,11,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(13,NULL,'health','โรคเดิมและระยะรอคอย ควรรู้ก่อนทำประกันสุขภาพ55555','โรคเด-มและระยะรอคอย-ควรร-ก-อนทำประก-นส-ขภาพ','ทำความเข้าใจการแจ้งประวัติสุขภาพ เงื่อนไขที่มักมีผลต่อการคุ้มครอง และวิธีเตรียมเอกสารให้ครบก่อนทำกรมธรรม์','',NULL,'assets/ภาพบทความ/77337558-11e1-43df-ab38-232551711980.png','','ไทยประกันชีวิต','','articles/pre-existing-waiting-period.html','ปรึกษาแผนนี้',1,0,1,12,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 20:34:04'),(14,NULL,'','หลังทำกรมธรรม์แล้ว ทีมงานช่วยดูแลอะไรได้บ้าง','หล-งทำกรมธรรม-แล-ว-ท-มงานช-วยด-แลอะไรได-บ-าง','ตั้งแต่การอธิบายเอกสาร การประสานงานเคลม ไปจนถึงการทบทวนแผนประกันเมื่อชีวิตหรือเป้าหมายเปลี่ยนไป',NULL,NULL,'assets/ภาพบทความ/d8cee835-4a35-4b77-bb11-1aeeb7ca022e.png',NULL,'ไทยประกันชีวิต',NULL,'articles/after-policy-support.html','ปรึกษาแผนนี้',1,0,1,13,NULL,NULL,NULL,'2026-05-26 14:21:03','2026-05-26 14:21:03');
