INSERT INTO `testimonials` (`id`, `customer_name`, `customer_role`, `avatar_letter`, `avatar_image`, `quote_text`, `rating`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'คุณแพร','ลูกค้าประกันสุขภาพ','พ','','ทีมงานอธิบายเงื่อนไขประกันสุขภาพชัดเจน ตอนต้องใช้สิทธิ์เคลมก็ช่วยประสานเอกสารให้ ไม่ต้องติด Call Center อย่างเดียว รู้สึกอุ่นใจมากขึ้น',5,0,1,'2026-05-26 14:21:03','2026-05-26 21:24:23'),(2,'คุณธนา','ลูกค้าประกันชีวิต','ธ',NULL,'ปรึกษาแผนประกันชีวิตและมรดกกับคุณแต้ม ได้คำตอบตรงประเด็น ไม่เร่งขาย ช่วยจัดลำดับความสำคัญตามงบประมาณจริง ๆ ของครอบครัวเรา',5,1,1,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(3,'คุณมิ้น','ลูกค้าแผนออมทรัพย์','ม',NULL,'วางแผนออมทรัพย์และลดหย่อนภาษีกับทีมสาขาบางนา เข้าใจง่าย มีการติดตามหลังทำกรมธรรม์ แนะนำเพื่อนมาปรึกษาอีกหลายคนแล้ว',5,2,1,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(4,'คุณนุช','ลูกค้าประกันโรคร้ายแรง','น',NULL,'เปรียบเทียบแผนประกันโรคร้ายแรงหลายแบบให้เข้าใจข้อดีข้อเสีย ตัดสินใจได้มั่นใจขึ้น หลังทำกรมธรรม์ยังมีทีมตัวแทนช่วยตอบคำถามตลอด',5,3,1,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(5,'คุณวิช','ลูกค้าแผนเกษียณ','ว',NULL,'วางแผนเกษียณและรายได้หลังเกษียณแบบเข้าใจง่าย ไม่ใช้ศัพท์ยาก ๆ บอกชัดว่าแต่ละแผนเหมาะกับเป้าหมายแบบไหน ประทับใจการบริการหลังขาย',5,4,1,'2026-05-26 14:21:03','2026-05-26 14:21:03'),(6,'คุณลูกน้ำ','ลูกค้าประกันสุขภาพครอบครัว','ล',NULL,'ทำประกันสุขภาพให้ทั้งครอบครัวในครั้งเดียว ทีมช่วยเช็กเงื่อนไขโรคเดิมและระยะรอคอยให้ละเอียด ตอนลูกป่วยก็ช่วยประสานเคลมจนจบ ไม่ต้องงงเอง',5,5,1,'2026-05-26 14:21:03','2026-05-26 14:21:03');
